// Package permbook is a bounded, authorization-carrying facade over
// gno.land/p/nt/groups/v0. It lets a realm define named permissions, grant
// them to addresses, revoke them, and ask "does this address currently hold
// this permission" without iterating anything.
//
// It holds no coins, imports no banker, stores no callbacks, and owns no
// package-level state. The importing realm allocates a *Book and keeps it
// private.
//
// # What this package adds, and what it does not
//
// It adds exactly four things to groups, and deliberately nothing else:
//
//  1. an ADMIN bound to the book, with a two-step handoff;
//  2. BOUNDS on permission count, holders per permission, and name shape;
//  3. permission semantics instead of membership semantics — no base set, no
//     metadata slot, and an empty permission is pruned rather than kept;
//  4. a cross-realm surface that is safe by CONSTRUCTION — the *groups.Group
//     is unexported and no method returns a mutable handle to it.
//
// Everything else — the B+-tree registry, the member sets, ordered
// iteration, the readonly views — comes from groups. This package writes no
// data-structure code.
//
// # The query
//
//	if !book.Has("withdraw", who) {
//		panic("not authorized")
//	}
//
// Has costs two independent B+-tree descents: O(log P) to find the
// permission, O(log H) to find the holder. It is NOT a function of how many
// permissions `who` already holds. That matters: every other named-permission
// implementation surveyed answers this by iterating the subject's
// permissions, which makes the most-privileged address the most expensive to
// check — the wrong asymptotic for an authorization check on a hot path.
//
// # Authorization
//
// Mutators take (_ int, rlm realm) and identify the principal as
// rlm.Previous().Address(), after asserting rlm.IsCurrent(). The consuming
// realm threads its own cur:
//
//	func Grant(cur realm, perm string, addr address) {
//		if err := book.Grant(0, cur, perm, addr); err != nil {
//			panic(err)
//		}
//	}
//
// IsCurrent() rejects a stale or stashed realm value, so a hostile realm
// cannot replay an old cur to impersonate the admin. This is the same shape
// as p/nt/ownable/v0 and p/nt/ownable/v0/exts/authorizable.
//
// # Lifecycle of a permission
//
// A permission comes into existence on its first grant and ceases to exist
// when its last holder is revoked. There is no create step and no reserved
// name. Has returns false either way, so the distinction is invisible to a
// caller and the book does not accumulate empty buckets.
//
//	(absent) ──Grant──> held by 1..MaxHoldersPerPermission ──Revoke last──> (absent)
//	                              │
//	                              └── DropPermission ──> (absent)
//
// # Admin handoff is two-step
//
// NominateAdmin records a nominee; only AcceptAdmin, called by that nominee,
// moves the admin. A one-step transfer to a well-formed-but-unowned address
// is permanently fatal — address.IsValid only checks bech32 form, so a
// mistyped address passes validation and leaves a book nobody can ever grant
// or revoke on again. This is the Y4 finding from the audit of Cosmic Bull's
// own r/permission_registry, carried forward.
//
// # Consumer contract — the parts this package CANNOT enforce
//
//  1. THREAD A LIVE cur. rlm.IsCurrent() proves the realm value came from a
//     live crossing frame, and rlm.Previous().Address() is then the principal
//     that crossed into your realm. A consumer that wraps a permbook mutator
//     in a NON-crossing exported helper resolves its importer's caller
//     instead of its importer — Class-2 designation forgery, in the consumer.
//     Call permbook mutators from your own crossing entrypoints, passing that
//     entrypoint's own cur.
//
//  2. DO NOT LEAK THE *Book. No method here returns a mutable handle, but a
//     consumer that exports its *Book — or returns it from a function
//     reachable by another realm — hands out every mutator on it, and
//     borrow rule #2 commits those writes under YOUR realm's authority. Keep
//     it in an unexported package-level variable.
//
//  3. Has ANSWERS ABOUT AN ADDRESS, NOT ABOUT YOUR CALLER. It performs no
//     authentication. Derive the address from your own crossing entrypoint's
//     cur.Previous().Address() and pass it in.
//
//  4. CHOOSE LIMITS DELIBERATELY. They are fixed for the life of a Book. A
//     consumer that needs different bounds later must allocate a second Book;
//     nothing here migrates state between them.
//
// # Note on the groups base set
//
// A groups.Group carries a base address set alongside its named roles. This
// package never writes to it, so it is provably empty for any Book, and
// "in the base set" can never mean "holds a permission".
package permbook

import (
	"errors"

	"gno.land/p/nt/groups/v0"
)

// Ceilings on what Limits may be configured to. They bound worst-case gas
// and storage for any Book, however the consumer configures it.
//
// MaxPermissionsCeiling is the one that bounds GAS rather than merely
// storage. Three operations walk every permission in the book at O(P log H)
// — Permissions, HasAny, and RevokeAll — and this ceiling is what bounds
// them. Everything else is logarithmic or paginated; see each method's own
// doc for its cost, which is authoritative.
//
// In particular HasAny is NOT a cheap variant of Has. Has is two tree
// descents; HasAny is a full walk of the registry. Do not put HasAny on a
// hot authorization path or inside a per-item render loop.
//
// These ceilings are not the objection this package raises against a shared
// registry. A shared registry's caps are rivalrous and unraisable because
// one immutable realm holds every tenant's state; here a consumer that needs
// more simply allocates another Book in its own realm, at no cost to anyone
// else.
const (
	MaxPermissionsCeiling = 256
	MaxHoldersCeiling     = 10000
	MaxNameLenCeiling     = 64
)

// Default limits, used by NewDefault.
const (
	DefaultMaxPermissions          = 64
	DefaultMaxHoldersPerPermission = 1024
	DefaultMaxNameLen              = 32
)

var (
	ErrUnauthorized      = errors.New("permbook: caller is not the admin")
	ErrNotLiveRealm      = errors.New("permbook: rlm is not the caller's live cur")
	ErrInvalidAddress    = errors.New("permbook: invalid address")
	ErrInvalidName       = errors.New("permbook: permission name must be 1..MaxNameLen chars, lowercase alphanumeric and underscore only")
	ErrInvalidLimits     = errors.New("permbook: limits must be positive and within the package ceilings")
	ErrAlreadyGranted    = errors.New("permbook: address already holds this permission")
	ErrNotGranted        = errors.New("permbook: address does not hold this permission")
	ErrPermissionLimit   = errors.New("permbook: permission limit reached for this book")
	ErrHolderLimit       = errors.New("permbook: holder limit reached for this permission")
	ErrNoPendingAdmin    = errors.New("permbook: no pending admin nomination")
	ErrNotPendingAdmin   = errors.New("permbook: caller is not the pending admin")
	ErrSameAdmin         = errors.New("permbook: nominee is already the admin")
	ErrUnknownPermission = errors.New("permbook: no such permission")
)

// Limits are fixed at construction and never change for the life of a Book.
type Limits struct {
	// MaxPermissions bounds how many distinct permission names may exist at
	// once. Because Permissions and RevokeAll walk all of them, this bounds
	// gas, not just storage.
	MaxPermissions int

	// MaxHoldersPerPermission bounds how many addresses may hold any one
	// permission. No operation iterates holders unpaginated, so this bounds
	// storage rather than gas.
	MaxHoldersPerPermission int

	// MaxNameLen bounds permission-name length.
	MaxNameLen int
}

// DefaultLimits returns the limits used by NewDefault.
func DefaultLimits() Limits {
	return Limits{
		MaxPermissions:          DefaultMaxPermissions,
		MaxHoldersPerPermission: DefaultMaxHoldersPerPermission,
		MaxNameLen:              DefaultMaxNameLen,
	}
}

func (l Limits) valid() bool {
	return l.MaxPermissions > 0 && l.MaxPermissions <= MaxPermissionsCeiling &&
		l.MaxHoldersPerPermission > 0 && l.MaxHoldersPerPermission <= MaxHoldersCeiling &&
		l.MaxNameLen > 0 && l.MaxNameLen <= MaxNameLenCeiling
}

// Book is a bounded set of named permissions with an admin. The zero value
// is not usable; construct with New or NewDefault.
//
// SECURITY: keep a *Book in an unexported variable. It is the capability.
// Every mutator on it is gated on the admin, but a realm that receives the
// pointer itself can invoke those mutators, and borrow rule #2 commits the
// writes under the ALLOCATING realm's authority.
type Book struct {
	g            *groups.Group
	admin        address
	pendingAdmin address
	lim          Limits
}

// New constructs an empty Book owned by admin, with explicit limits.
func New(admin address, lim Limits) (*Book, error) {
	if !admin.IsValid() {
		return nil, ErrInvalidAddress
	}
	if !lim.valid() {
		return nil, ErrInvalidLimits
	}
	return &Book{
		g:     groups.NewGroup(),
		admin: admin,
		lim:   lim,
	}, nil
}

// NewDefault constructs an empty Book owned by admin, with DefaultLimits.
func NewDefault(admin address) (*Book, error) {
	return New(admin, DefaultLimits())
}

// --- authorization ---

// principal returns the address that crossed into the caller's realm, after
// proving rlm is a live crossing frame rather than a stashed value.
func principal(_ int, rlm realm) (address, error) {
	if !rlm.IsCurrent() {
		return address(""), ErrNotLiveRealm
	}
	return rlm.Previous().Address(), nil
}

// assertAdmin resolves the principal from rlm and requires it to be the
// book's admin.
func (b *Book) assertAdmin(_ int, rlm realm) error {
	who, err := principal(0, rlm)
	if err != nil {
		return err
	}
	if who != b.admin {
		return ErrUnauthorized
	}
	return nil
}

// --- grant and revoke ---

// Grant gives addr the named permission. Admin only.
//
// The permission is created if it does not exist. Granting a permission the
// address already holds returns ErrAlreadyGranted rather than silently
// succeeding, so a consumer cannot mistake a no-op for a state change.
func (b *Book) Grant(_ int, rlm realm, perm string, addr address) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !b.validName(perm) {
		return ErrInvalidName
	}
	if !addr.IsValid() {
		return ErrInvalidAddress
	}

	r, found := b.g.GetRole(perm)
	if !found {
		if b.g.RoleCount() >= b.lim.MaxPermissions {
			return ErrPermissionLimit
		}
		var err error
		r, err = b.g.AddRole(perm)
		if err != nil {
			return err
		}
	}

	members := r.Members()
	if members.Has(addr) {
		return ErrAlreadyGranted
	}
	if members.Size() >= b.lim.MaxHoldersPerPermission {
		// No rollback is needed here, and adding one would be dead code.
		//
		// Reaching this branch requires Size() >= MaxHoldersPerPermission,
		// and Limits.valid guarantees MaxHoldersPerPermission >= 1, so
		// Size() >= 1. A permission created moments ago above has Size() 0
		// and therefore cannot reach this branch at all. So the permission
		// this rejects always pre-existed with holders, and returning leaves
		// no orphan empty bucket occupying a MaxPermissions slot.
		//
		// That argument depends on Limits.valid rejecting a zero holder
		// limit. If that ever changes, this branch needs an undo.
		return ErrHolderLimit
	}

	members.Add(addr)
	return nil
}

// Revoke removes the named permission from addr. Admin only.
//
// Revoking the last holder removes the permission itself, freeing its slot
// against MaxPermissions. Has reports false either way, so this is invisible
// to a caller and keeps the book from accumulating empty buckets.
func (b *Book) Revoke(_ int, rlm realm, perm string, addr address) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !b.revokeOne(perm, addr) {
		return ErrNotGranted
	}
	return nil
}

// revokeOne removes addr from perm and prunes the permission if it is left
// empty. Reports whether addr actually held it. No authorization: every
// caller is inside this package and has already gated on the admin.
func (b *Book) revokeOne(perm string, addr address) bool {
	r, found := b.g.GetRole(perm)
	if !found {
		return false
	}
	members := r.Members()
	if !members.Remove(addr) {
		return false
	}
	if members.Size() == 0 {
		b.g.RemoveRole(perm)
	}
	return true
}

// RevokeAll removes addr from every permission in the book and reports how
// many were removed. Admin only.
//
// Cost is O(P log H) in the book's permission count — bounded by
// MaxPermissions, which is why that limit has a ceiling.
//
// Implementation note: the permission names are collected FIRST, into a
// value slice, and the registry is mutated only after that walk returns.
// groups documents that mutating the role registry mid-iteration can panic
// and abort the transaction.
func (b *Book) RevokeAll(_ int, rlm realm, addr address) (int, error) {
	if err := b.assertAdmin(0, rlm); err != nil {
		return 0, err
	}
	names := b.g.RolesContaining(addr)
	n := 0
	for _, perm := range names {
		if b.revokeOne(perm, addr) {
			n++
		}
	}
	return n, nil
}

// DropPermission removes a permission and every grant of it. Admin only.
//
// Cost is O(log P): groups discards the whole member set with the role and
// does not walk it, so this is safe for a permission with many holders.
func (b *Book) DropPermission(_ int, rlm realm, perm string) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !b.g.RemoveRole(perm) {
		return ErrUnknownPermission
	}
	return nil
}

// --- admin handoff ---

// NominateAdmin records a nominee for the admin role. Admin only. The
// handoff does NOT take effect until the nominee calls AcceptAdmin, and a
// nomination may be withdrawn with CancelNomination until then.
func (b *Book) NominateAdmin(_ int, rlm realm, nominee address) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if !nominee.IsValid() {
		return ErrInvalidAddress
	}
	if nominee == b.admin {
		return ErrSameAdmin
	}
	b.pendingAdmin = nominee
	return nil
}

// CancelNomination withdraws a pending nomination. Admin only.
func (b *Book) CancelNomination(_ int, rlm realm) error {
	if err := b.assertAdmin(0, rlm); err != nil {
		return err
	}
	if b.pendingAdmin == address("") {
		return ErrNoPendingAdmin
	}
	b.pendingAdmin = address("")
	return nil
}

// AcceptAdmin completes a pending handoff. Only the nominee may call it.
func (b *Book) AcceptAdmin(_ int, rlm realm) error {
	who, err := principal(0, rlm)
	if err != nil {
		return err
	}
	if b.pendingAdmin == address("") {
		return ErrNoPendingAdmin
	}
	if who != b.pendingAdmin {
		return ErrNotPendingAdmin
	}
	b.admin = who
	b.pendingAdmin = address("")
	return nil
}

// --- queries ---
//
// Queries perform NO caller authentication. They answer questions about an
// address, not about your caller. See consumer-contract clause 3.

// Has reports whether addr currently holds the named permission.
//
// Two B+-tree descents, O(log P + log H). Independent of how many other
// permissions addr holds. Never panics; unknown permissions report false.
func (b *Book) Has(perm string, addr address) bool {
	r, found := b.g.GetRole(perm)
	if !found {
		return false
	}
	return r.Members().Has(addr)
}

// HasAny reports whether addr holds any permission at all. O(P log H).
func (b *Book) HasAny(addr address) bool {
	return b.g.HasAny(addr)
}

// Permissions returns the names addr holds, in lexicographic order, or nil.
// O(P log H) — bounded by MaxPermissions.
func (b *Book) Permissions(addr address) []string {
	return b.g.RolesContaining(addr)
}

// PermissionCount returns how many distinct permissions currently exist.
func (b *Book) PermissionCount() int {
	return b.g.RoleCount()
}

// PermissionNames returns up to count permission names in lexicographic
// order, starting at offset. Paginated so the caller, not the book, chooses
// how much work a single call does.
func (b *Book) PermissionNames(offset, count int) []string {
	if count <= 0 {
		return nil
	}
	var out []string
	b.g.IterateRoles(offset, count, func(rr *groups.ReadonlyRole) bool {
		out = append(out, rr.Name())
		return false
	})
	return out
}

// HolderCount returns how many addresses hold the named permission, or 0 if
// it does not exist.
func (b *Book) HolderCount(perm string) int {
	r, found := b.g.GetRole(perm)
	if !found {
		return 0
	}
	return r.Members().Size()
}

// Holders returns up to count holders of the named permission, in sorted
// order, starting at offset. Paginated for the same reason as
// PermissionNames. Returns nil for an unknown permission.
func (b *Book) Holders(perm string, offset, count int) []address {
	if count <= 0 {
		return nil
	}
	r, found := b.g.GetRole(perm)
	if !found {
		return nil
	}
	var out []address
	r.Members().IterateByOffset(offset, count, func(a address) bool {
		out = append(out, a)
		return false
	})
	return out
}

// Admin returns the book's current admin.
func (b *Book) Admin() address {
	return b.admin
}

// PendingAdmin returns the nominated-but-not-yet-accepted admin, or the
// empty address if there is no pending nomination.
func (b *Book) PendingAdmin() address {
	return b.pendingAdmin
}

// IsAdmin reports whether addr is the book's admin.
func (b *Book) IsAdmin(addr address) bool {
	return addr == b.admin
}

// Limits returns the book's fixed limits.
func (b *Book) Limits() Limits {
	return b.lim
}

// --- names ---

// validName restricts permission names to lowercase alphanumerics and
// underscores, within the book's MaxNameLen.
//
// Beyond hygiene this is a security property: permission names end up in
// composite trust decisions and in rendered output, so no delimiter,
// whitespace, or markdown character may enter one.
func (b *Book) validName(name string) bool {
	if name == "" || len(name) > b.lim.MaxNameLen {
		return false
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

// Package permbook_demo is the reference consumer for the permbook
// permission primitive. It exists to make permbook's central claim
// falsifiable on a live chain.
//
// That claim is: a permission revoked in transaction N is refused in
// transaction N+1. A pure package cannot demonstrate this — a vm/qeval is a
// single ephemeral evaluation and nothing it writes survives it. Only a
// realm, called across several transactions, can show a grant taking effect
// and then a revoke taking it away. So this realm is not a decoration on the
// primitive; it is the experiment.
//
// # What it does
//
// Two permission-gated actions, deliberately trivial so that the only
// interesting thing about them is the gate:
//
//   - bump   — increments a counter and records who did it
//   - notice — replaces a short public notice
//
// Neither action is reachable without the corresponding permission. The
// deployer is the book's admin and is the only account that may grant or
// revoke. Holding "bump" confers no authority over the book itself: a holder
// cannot grant, cannot revoke, and cannot nominate. That separation is the
// property being demonstrated.
//
// # How it wires permbook correctly
//
// This realm is also the worked example of permbook's consumer contract:
//
//   - every permbook mutator is called from a CROSSING entrypoint, passing
//     that entrypoint's own cur, so the principal permbook resolves is this
//     realm's immediate caller (contract 1);
//   - the *Book is an unexported package-level var and is never returned
//     across a realm boundary (contract 2);
//   - Has is asked about an address this realm derived itself from
//     cur.Previous().Address(), never about a parameter (contract 3);
//   - the limits are chosen once, at init, and documented below (contract 4).
//
// This realm holds no coins and imports no banker. Every crossing entrypoint
// rejects attached coins; the read views are non-crossing, which MsgCall will
// not dispatch to, so no transaction can attach coins to one.
package permbook_demo

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/permbook"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// The permission names this realm gates on. They are constants rather than
// caller-supplied strings for the gated actions, so a typo cannot silently
// create an unenforced gate.
const (
	PermBump   = "bump"
	PermNotice = "notice"
)

const (
	// The book's limits. Deliberately far below permbook's ceilings: this
	// realm needs two permissions and a handful of holders, and a bound
	// should describe what the application actually does rather than the
	// most the library would tolerate. A few spare slots are left so the
	// permission limit can be exercised on-chain without wedging the demo.
	MaxPermissions = 8
	MaxHolders     = 32
	MaxNameLen     = 24

	// MaxNoticeLen bounds the public notice. A BYTE length, not a rune
	// count, because its job is to bound storage.
	MaxNoticeLen = 200

	// MaxListed caps how many rows any single query or view returns, so no
	// read is unbounded regardless of how full the book is.
	MaxListed = 50
)

// book is the permission set. It is unexported and never returned: handing a
// *permbook.Book across a realm boundary would hand out every mutator on it,
// and borrow rule #2 commits those writes under THIS realm's authority
// (permbook consumer contract 2).
var book *permbook.Book

// The state the gated actions move. This is the observable evidence that a
// gate was open at one height and closed at another.
var (
	bumps          int64
	lastBumper     address
	lastBumpHeight int64

	notice           string
	noticeAuthor     address
	noticeSetAtBlock int64
)

// demoLimits are the limits every Book this realm constructs is given.
func demoLimits() permbook.Limits {
	return permbook.Limits{
		MaxPermissions:          MaxPermissions,
		MaxHoldersPerPermission: MaxHolders,
		MaxNameLen:              MaxNameLen,
	}
}

func init() {
	// The package deployer becomes the book's admin: on-chain, AddPackage
	// runs init with the message creator as origin caller, and a
	// MsgAddPackage's creator is never zero.
	//
	// Under `gno test` there is no MsgAddPackage, so the origin context is
	// empty and the address is invalid; the test file's own init constructs
	// the book instead. On-chain that branch is unreachable, and if it ever
	// were reached the realm would deploy INERT — book stays nil and every
	// entrypoint aborts rather than running ungated. For a realm that holds
	// no value and gates two trivial actions, inert is the safe direction.
	// TestInertRealmFailsClosed exercises exactly that state, so the claim
	// is test-backed rather than argued.
	//
	// An audit of this file recommended panicking here instead, to make the
	// invariant structural. That was tried and rejected on evidence: the
	// realm's init runs before the test file's, so a panic makes the whole
	// package unloadable under `gno test` —
	//
	//	permbook_demo: no deploy-time admin (code=gnoUnknownError)
	//	FAIL: 0 build errors, 1 test errors
	//
	// which trades all 16 tests, including the central authorization claim,
	// for a guard on a branch the audit itself could not reach on-chain.
	// The early return plus a fail-closed test is the better trade.
	//
	// The deploy-time obligation this leaves is real and belongs in the
	// runbook, not in the code: check Ready() immediately after deploying
	// and treat false as a FAILED deploy, because it is unrecoverable —
	// nothing assigns book after init, so a fresh path is the only remedy.
	deployer := unsafe.OriginCaller()
	if !deployer.IsValid() {
		return
	}
	b, err := permbook.New(deployer, demoLimits())
	if err != nil {
		panic(err)
	}
	book = b
}

// Ready reports whether init captured a deploy-time admin and constructed
// the book. False means the realm is inert; see the note in init.
func Ready() bool { return book != nil }

// rejectStraySend aborts if an EOA attached coins to an entrypoint that has
// no use for them. This realm never holds value; without this guard a
// mistyped send would be silently absorbed by the realm bank.
func rejectStraySend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this entrypoint does not accept coins")
	}
}

// --- the gated actions ----------------------------------------------------
//
// Each one asks permbook about an address IT derived from its own crossing
// frame. The address is never a parameter (consumer contract 3).

// Bump increments the counter. Requires the "bump" permission.
//
// This is the experiment: call it with the permission and it succeeds; have
// the admin revoke, call it again in a later transaction, and it aborts.
func Bump(cur realm) string {
	rejectStraySend(cur)

	caller := cur.Previous().Address()
	if !book.Has(PermBump, caller) {
		panic("permission denied: " + PermBump)
	}

	now := runtime.ChainHeight()
	bumps++
	lastBumper = caller
	lastBumpHeight = now

	chain.Emit("Bumped",
		"by", caller.String(),
		"count", itoa(bumps),
		"height", itoa(now),
	)
	return "bump " + itoa(bumps) + " at height " + itoa(now)
}

// SetNotice replaces the public notice. Requires the "notice" permission.
//
// It exists so the demo shows two INDEPENDENT permissions on one book:
// holding "bump" does not let an address set the notice, and revoking one
// leaves the other intact.
func SetNotice(cur realm, text string) string {
	rejectStraySend(cur)

	caller := cur.Previous().Address()
	if !book.Has(PermNotice, caller) {
		panic("permission denied: " + PermNotice)
	}
	if text == "" {
		panic("notice must not be empty")
	}
	if len(text) > MaxNoticeLen {
		panic("notice exceeds " + itoa(MaxNoticeLen) + " bytes")
	}

	now := runtime.ChainHeight()
	notice = text
	noticeAuthor = caller
	noticeSetAtBlock = now

	chain.Emit("NoticeSet", "by", caller.String(), "height", itoa(now))
	return "notice set at height " + itoa(now)
}

// --- administration -------------------------------------------------------
//
// Every one of these is a crossing entrypoint that threads its OWN cur into
// permbook, so permbook resolves this realm's immediate caller as the
// principal (consumer contract 1). None of them takes a caller address as an
// argument; there is nothing here to forge.

// Grant gives addr a permission. Admin only.
func Grant(cur realm, perm string, addr address) string {
	rejectStraySend(cur)
	if err := book.Grant(0, cur, perm, addr); err != nil {
		panic(err)
	}
	chain.Emit("Granted", "permission", perm, "to", addr.String())
	return "granted " + perm + " to " + addr.String()
}

// Revoke removes a permission from addr. Admin only.
//
// The revoke is committed by this transaction. Any later transaction that
// reaches a gate on that permission is refused — that is the claim.
func Revoke(cur realm, perm string, addr address) string {
	rejectStraySend(cur)
	if err := book.Revoke(0, cur, perm, addr); err != nil {
		panic(err)
	}
	chain.Emit("Revoked", "permission", perm, "from", addr.String())
	return "revoked " + perm + " from " + addr.String()
}

// RevokeAll removes every permission addr holds and reports how many.
// Admin only.
func RevokeAll(cur realm, addr address) string {
	rejectStraySend(cur)
	n, err := book.RevokeAll(0, cur, addr)
	if err != nil {
		panic(err)
	}
	chain.Emit("RevokedAll", "from", addr.String(), "count", itoa(int64(n)))
	return "revoked " + itoa(int64(n)) + " permission(s) from " + addr.String()
}

// DropPermission removes a permission and every grant of it. Admin only.
func DropPermission(cur realm, perm string) string {
	rejectStraySend(cur)
	if err := book.DropPermission(0, cur, perm); err != nil {
		panic(err)
	}
	chain.Emit("PermissionDropped", "permission", perm)
	return "dropped " + perm
}

// NominateAdmin records a nominee for the admin role. Admin only. The
// handoff does not take effect until the nominee calls AcceptAdmin.
func NominateAdmin(cur realm, nominee address) string {
	rejectStraySend(cur)
	if err := book.NominateAdmin(0, cur, nominee); err != nil {
		panic(err)
	}
	chain.Emit("AdminNominated", "nominee", nominee.String())
	return "nominated " + nominee.String()
}

// CancelNomination withdraws a pending nomination. Admin only.
func CancelNomination(cur realm) string {
	rejectStraySend(cur)
	if err := book.CancelNomination(0, cur); err != nil {
		panic(err)
	}
	chain.Emit("AdminNominationCancelled")
	return "nomination cancelled"
}

// AcceptAdmin completes a pending handoff. Only the nominee may call it.
func AcceptAdmin(cur realm) string {
	rejectStraySend(cur)
	if err := book.AcceptAdmin(0, cur); err != nil {
		panic(err)
	}
	who := cur.Previous().Address()
	chain.Emit("AdminAccepted", "admin", who.String())
	return "admin is now " + who.String()
}

// --- read-only views ------------------------------------------------------
//
// None of these authorizes anything, and none of them authenticates its
// caller. They answer questions about an address (permbook consumer
// contract 3).

// Height returns the chain height this realm is reading as "now".
func Height() int64 { return runtime.ChainHeight() }

// Admin returns the book's current admin.
func Admin() string { return book.Admin().String() }

// PendingAdmin returns the nominated-but-not-yet-accepted admin, or "".
func PendingAdmin() string { return book.PendingAdmin().String() }

// Has reports whether addr holds perm. This is the primitive's core query,
// exposed verbatim so it can be checked from off-chain.
func Has(perm string, addr address) bool { return book.Has(perm, addr) }

// CanBump reports whether addr would be allowed to call Bump right now.
func CanBump(addr address) bool { return book.Has(PermBump, addr) }

// PermissionsOf returns the permissions addr holds, comma-separated in
// lexicographic order, or "" for none. Names are restricted by permbook to
// lowercase alphanumerics and underscore, so a comma can never appear in
// one and this encoding is unambiguous.
func PermissionsOf(addr address) string {
	return join(book.Permissions(addr))
}

// PermissionCount returns how many distinct permissions currently exist.
func PermissionCount() int { return book.PermissionCount() }

// Permissions returns up to MaxListed permission names, comma-separated in
// lexicographic order.
func Permissions() string {
	return join(book.PermissionNames(0, MaxListed))
}

// HolderCount returns how many addresses hold perm, or 0 if it does not
// exist.
func HolderCount(perm string) int { return book.HolderCount(perm) }

// Holders returns up to MaxListed holders of perm, comma-separated in
// sorted order.
func Holders(perm string) string {
	hs := book.Holders(perm, 0, MaxListed)
	out := ""
	for i, h := range hs {
		if i > 0 {
			out += ","
		}
		out += h.String()
	}
	return out
}

// Bumps returns how many times Bump has succeeded.
func Bumps() int64 { return bumps }

// LastBump describes the most recent successful Bump, or "none".
func LastBump() string {
	if bumps == 0 {
		return "none"
	}
	return lastBumper.String() + " at height " + itoa(lastBumpHeight)
}

// Notice returns the current public notice, or "".
func Notice() string { return notice }

// Limits reports the book's fixed limits.
func Limits() string {
	l := book.Limits()
	return "permissions=" + itoa(int64(l.MaxPermissions)) +
		" holders=" + itoa(int64(l.MaxHoldersPerPermission)) +
		" namelen=" + itoa(int64(l.MaxNameLen))
}

// --- rendering ------------------------------------------------------------

// realmPath is this realm's gnoweb prefix, used to build view links.
const realmPath = "/r/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/permbook_demo"

// Render serves three views, selected by path.
//
//	(empty)  summary, the permission table, and the gated state
//	holders  every permission with its holders, up to MaxListed each
//	about    what this realm is and why it exists
//
// An inert realm (see init) reports that instead of rendering. Every view
// reads the book, so without this the gnoweb page would abort on a nil
// dereference — which is exactly the moment an operator needs it to say what
// is wrong. The typed read functions still abort when inert; Ready is the
// probe that answers the question without panicking.
func Render(path string) string {
	if !Ready() {
		return "# Permission demo\n\n" +
			"This realm is **inert**: init captured no deploy-time admin, so " +
			"no permission book exists. Every entrypoint aborts and nothing " +
			"runs ungated. The state is unrecoverable — redeploy to a fresh " +
			"path.\n"
	}

	switch normalizePath(path) {
	case "holders":
		return renderHeader() + renderHolders()
	case "about":
		return renderHeader() + renderAbout()
	default:
		return renderHeader() + renderPermissions() + renderState()
	}
}

func renderHeader() string {
	s := "# Permission demo\n\n"
	s += "Reference consumer for [permbook](/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/permbook).\n\n"
	s += "- height: " + itoa(runtime.ChainHeight()) + "\n"
	s += "- admin: " + sanitize.InlineText(book.Admin().String()) + "\n"
	if p := book.PendingAdmin(); p != address("") {
		s += "- pending admin: " + sanitize.InlineText(p.String()) + "\n"
	}
	s += "- permissions: " + itoa(int64(book.PermissionCount())) +
		" / " + itoa(int64(MaxPermissions)) + "\n\n"
	s += "[summary](" + realmPath + ") · "
	s += "[holders](" + realmPath + ":holders) · "
	s += "[about](" + realmPath + ":about)\n\n"
	return s
}

func renderPermissions() string {
	names := book.PermissionNames(0, MaxListed)

	s := "## Permissions\n\n"
	if len(names) == 0 {
		return s + "_none granted yet._\n\n"
	}
	s += "| permission | holders | gates |\n|---|---|---|\n"
	for _, n := range names {
		s += "| " + sanitize.InlineText(n) +
			" | " + itoa(int64(book.HolderCount(n))) +
			" | " + gateFor(n) + " |\n"
	}
	if book.PermissionCount() > len(names) {
		s += "\nShowing the first " + itoa(int64(len(names))) + " of " +
			itoa(int64(book.PermissionCount())) + ".\n"
	}
	return s + "\n"
}

// gateFor names the entrypoint a permission opens, or says it opens none.
// A permission with no gate is not a bug: the admin may grant a name this
// realm does not read, and saying so plainly is better than implying every
// permission is enforced somewhere.
func gateFor(perm string) string {
	switch perm {
	case PermBump:
		return "`Bump`"
	case PermNotice:
		return "`SetNotice`"
	default:
		return "_no entrypoint reads this_"
	}
}

func renderHolders() string {
	names := book.PermissionNames(0, MaxListed)

	s := "## Holders\n\n"
	if len(names) == 0 {
		return s + "_none granted yet._\n\n"
	}
	for _, n := range names {
		total := book.HolderCount(n)
		s += "**" + sanitize.InlineText(n) + "** — " + itoa(int64(total)) + " holder(s)\n\n"
		for _, h := range book.Holders(n, 0, MaxListed) {
			s += "- " + sanitize.InlineText(h.String()) + "\n"
		}
		if total > MaxListed {
			s += "\n_Showing the first " + itoa(int64(MaxListed)) + " of " +
				itoa(int64(total)) + "._\n"
		}
		s += "\n"
	}
	return s
}

func renderState() string {
	s := "## Gated state\n\n"
	s += "- bumps: " + itoa(bumps) + "\n"
	s += "- last bump: "
	if bumps == 0 {
		s += "_none_\n"
	} else {
		s += sanitize.InlineText(lastBumper.String()) +
			" at height " + itoa(lastBumpHeight) + "\n"
	}
	s += "\n### Notice\n\n"
	if notice == "" {
		return s + "_none set._\n\n"
	}
	// Blockquote, not InlineText: the slot IS a blockquote, so the helper
	// whose contract covers the slot is the one to use. Blockquote emits
	// its own envelope, so no manual "> " prefix here.
	s += sanitize.Blockquote(notice)
	s += "set by " + sanitize.InlineText(noticeAuthor.String()) +
		" at height " + itoa(noticeSetAtBlock) + "\n\n"
	return s
}

func renderAbout() string {
	return "## About\n\n" +
		"Two permission-gated entrypoints, deliberately trivial so that the " +
		"only interesting thing about them is the gate:\n\n" +
		"- `Bump` requires `" + PermBump + "`\n" +
		"- `SetNotice` requires `" + PermNotice + "`\n\n" +
		"The deployer is the book's admin and is the only account that may " +
		"grant or revoke. **Holding a permission confers no authority over " +
		"the book**: a holder cannot grant, cannot revoke, and cannot " +
		"nominate an admin.\n\n" +
		"The claim this realm makes falsifiable is that a permission revoked " +
		"in one transaction is refused in the next. Grant `" + PermBump +
		"`, call `Bump` — it succeeds. Revoke, call `Bump` again — it " +
		"aborts. A pure package cannot show that; only a realm called across " +
		"several transactions can.\n\n" +
		"This realm holds no coins and imports no banker. Every crossing " +
		"entrypoint rejects attached coins, and the read views are " +
		"non-crossing so no transaction can attach coins to one.\n\n" +
		"- max permissions: " + itoa(int64(MaxPermissions)) + "\n" +
		"- max holders per permission: " + itoa(int64(MaxHolders)) + "\n" +
		"- max permission name length: " + itoa(int64(MaxNameLen)) + "\n" +
		"- max notice length: " + itoa(int64(MaxNoticeLen)) + " bytes\n"
}

// normalizePath reduces a gnoweb render path to a bare view name, so "",
// "/", "holders" and "/holders/" all select the same view.
func normalizePath(path string) string {
	for len(path) > 0 && path[0] == '/' {
		path = path[1:]
	}
	for len(path) > 0 && path[len(path)-1] == '/' {
		path = path[:len(path)-1]
	}
	return path
}

// --- helpers --------------------------------------------------------------

// join comma-separates names. Safe because permbook restricts permission
// names to lowercase alphanumerics and underscore, so no name can contain
// the delimiter.
func join(names []string) string {
	out := ""
	for i, n := range names {
		if i > 0 {
			out += ","
		}
		out += n
	}
	return out
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }
